inline bool VerifyServerPayload(flatbuffers::Verifier &verifier, const void *obj, ServerPayload type) {
  switch (type) {
    case ServerPayload_NONE: {
      return true;
    }
    case ServerPayload_WorldSnapshot: {
      auto ptr = reinterpret_cast<const game::wire::WorldSnapshot *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerPayload_DialogueEvent: {
      auto ptr = reinterpret_cast<const game::wire::DialogueEvent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ServerPayload_AudioEvent: {
      auto ptr = reinterpret_cast<const game::wire::AudioEvent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyServerPayloadVector(flatbuffers::Verifier &verifier, const flatbuffers::Vector<flatbuffers::Offset<void>> *values, const flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyServerPayload(
        verifier,  values->Get(i), types->GetEnum<ServerPayload>(i))) {
      return false;
    }
  }
  return true;
}

inline bool VerifyClientPayload(flatbuffers::Verifier &verifier, const void *obj, ClientPayload type) {
  switch (type) {
    case ClientPayload_NONE: {
      return true;
    }
    case ClientPayload_Hello: {
      auto ptr = reinterpret_cast<const game::wire::Hello *>(obj);
      return verifier.VerifyTable(ptr);
    }
    case ClientPayload_ChatToAgent: {
      auto ptr = reinterpret_cast<const game::wire::ChatToAgent *>(obj);
      return verifier.VerifyTable(ptr);
    }
    default: return true;
  }
}

inline bool VerifyClientPayloadVector(flatbuffers::Verifier &verifier, const flatbuffers::Vector<flatbuffers::Offset<void>> *values, const flatbuffers::Vector<uint8_t> *types) {
  if (!values || !types) return !values && !types;
  if (values->size() != types->size()) return false;
  for (flatbuffers::uoffset_t i = 0; i < values->size(); ++i) {
    if (!VerifyClientPayload(
        verifier,  values->Get(i), types->GetEnum<ClientPayload>(i))) {
      return false;
    }
  }
  return true;
}

inline const game::wire::ServerMessage *GetServerMessage(const void *buf) {
  return flatbuffers::GetRoot<game::wire::ServerMessage>(buf);
}

inline const game::wire::ServerMessage *GetSizePrefixedServerMessage(const void *buf) {
  return flatbuffers::GetSizePrefixedRoot<game::wire::ServerMessage>(buf);
}

inline bool VerifyServerMessageBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifyBuffer<game::wire::ServerMessage>(nullptr);
}

inline bool VerifySizePrefixedServerMessageBuffer(
    flatbuffers::Verifier &verifier) {
  return verifier.VerifySizePrefixedBuffer<game::wire::ServerMessage>(nullptr);
}

inline void FinishServerMessageBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<game::wire::ServerMessage> root) {
  fbb.Finish(root);
}

inline void FinishSizePrefixedServerMessageBuffer(
    flatbuffers::FlatBufferBuilder &fbb,
    flatbuffers::Offset<game::wire::ServerMessage> root) {
  fbb.FinishSizePrefixed(root);
}

